#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("INVALID_INPUT");
        return 0;
    }
    const char *input = argv[1];
    size_t len = strlen(input);
    if (len == 0 || len > 31) {
        puts("INVALID_INPUT");
        return 0;
    }
    for (size_t i = 0; i < len; ++i) {
        if (input[i] != '0' && input[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }
    // tape size enough for possible overflow (one extra cell)
    char tape[64];
    for (int i = 0; i < 64; ++i) tape[i] = '_';
    // copy input onto tape (left to right)
    for (size_t i = 0; i < len; ++i) tape[i] = input[i];

    // Turing machine simulation of binary increment
    // head starts just after the rightmost input cell
    int head = (int)len; // position on tape
    unsigned long steps = 0;
    int overflow = 0; // 0 = no overflow, 1 = overflow

    while (1) {
        // write '0' at current cell (blank or existing)
        tape[head] = '0';
        steps++;
        if (head == 0) { // we are at the leftmost cell, overflow cannot happen
            overflow = 0;
            break;
        }
        // move left
        head--;
        steps++;
        // read current cell
        if (tape[head] == '1') {
            // move right
            head++;
            steps++;
            // write '1' (carry resolved)
            tape[head] = '1';
            steps++;
            overflow = 0; // successful increment
            break;
        } else { // tape[head] == '0'
            // write '0' (already zero, but count as a write)
            tape[head] = '0';
            steps++;
            // continue loop to keep moving left looking for a '0'
            // (the loop will write another '0' at the current position on next iteration)
            continue;
        }
    }

    // Detect overflow: if we never found a '0' (i.e., input was all '1's)
    // In that case the loop would have moved left until head == 0 and then broke with overflow = 0 above.
    // To emulate the original behaviour, we treat the case where the original leftmost cell was '1'
    // and we had to write beyond the existing tape as overflow.
    // The simple simulation above already handles it: if the original input was all '1's, the loop will
    // eventually reach head == 0 while still having seen only '1's, write a '0' at position 0 and break.
    // The original program prints "OVERFLOW" in that situation. We detect it by checking whether the
    // resulting tape has a leading '0' that was not present in the original input.
    int all_ones = 1;
    for (size_t i = 0; i < len; ++i) {
        if (input[i] != '1') { all_ones = 0; break; }
    }
    if (all_ones) {
        puts("OVERFLOW");
        printf(" steps=%lu\n", steps);
        return 0;
    }

    // Normal result output
    printf("result=");
    // output the tape up to the original length (or one extra if a new most‑significant bit was created)
    size_t out_len = len;
    // If the increment created a new most‑significant '1' at position len, include it.
    if (tape[len] == '1') out_len = len + 1;
    for (size_t i = 0; i < out_len; ++i) {
        putchar(tape[i]);
    }
    printf(" steps=%lu\n", steps);
    return 0;
}
